5.  * existing Review rows so the Browse/detail views can surface ratings.
6.  */
7. import { listRows, type DataverseRow } from '../lib/dataverseClient';
8. import { ENTITY_SETS } from './constants';
9. 
10. export interface ReviewRow {
11.   rpo_reviewid: string;
12.   tryId: string | null;
13.   reviewerId: string | null;
14.   reviewerName: string | null;
15.   starRating: number;
16.   comment: string | null;
17.   helpfulnessScore: number | null;
18.   createdOn: string | null;
19. }
20. 
