37.     rpo_reviewid: String(row.rpo_reviewid),
38.     tryId: (row._rpo_tryid_value as string | null | undefined) ?? null,
39.     reviewerId: (row._rpo_reviewerid_value as string | null | undefined) ?? null,
40.     reviewerName:
41.       (row['_rpo_reviewerid_value@OData.Community.Display.V1.FormattedValue'] as string | undefined) ?? null,
42.     starRating: (row.rpo_starrating as number | undefined) ?? 0,
43.     comment: (row.rpo_comment as string | null | undefined) ?? null,
44.     helpfulnessScore: (row.rpo_helpfulnessscore as number | null | undefined) ?? null,
