1. /**
2.  * Aggregates Try/Review data per PoutineSubmission for the Browse feed and
3.  * detail view (Phase 2). Read-only: Try/Review *creation* is Phase 3.
4.  */
5. import { listTriesForSubmissions, type TryRow } from './tries';
6. import { listReviewsForTries, type ReviewRow } from './reviews';
7. 
8. export interface SubmissionAggregate {
9.   tryCount: number;
10.   reviewCount: number;
11.   /** Simple (unweighted) average of star ratings, or null when there are no reviews yet. */
12.   averageRating: number | null;
13. }
14. 
15. function emptyAggregate(): SubmissionAggregate {
16.   return { tryCount: 0, reviewCount: 0, averageRating: null };
17. }
18. 
19. /**
20.  * Computes try count / review count / average rating for each of the given
21.  * submission ids in just two Dataverse round-trips (all Tries for the set,
22.  * then all Reviews for those Tries), regardless of how many submissions are
23.  * passed in — appropriate at this app's demo scale.
24.  */
25. export async function getAggregatesForSubmissions(
26.   submissionIds: string[],
27. ): Promise<Map<string, SubmissionAggregate>> {
28.   const aggregates = new Map<string, SubmissionAggregate>();
29.   for (const id of submissionIds) aggregates.set(id, emptyAggregate());
30.   if (submissionIds.length === 0) return aggregates;
31. 
32.   const tries = await listTriesForSubmissions(submissionIds);
33.   const tryIdToSubmissionId = new Map<string, string>();
34.   for (const t of tries) {
35.     if (!t.poutineSubmissionId) continue;
36.     const agg = aggregates.get(t.poutineSubmissionId);
37.     if (agg) agg.tryCount += 1;
38.     tryIdToSubmissionId.set(t.rpo_tryid, t.poutineSubmissionId);
39.   }
40. 
41.   const tryIds = tries.map((t) => t.rpo_tryid);
42.   const reviews = await listReviewsForTries(tryIds);
43.   const ratingSums = new Map<string, { sum: number; count: number }>();
44.   for (const r of reviews) {
45.     const submissionId = r.tryId ? tryIdToSubmissionId.get(r.tryId) : undefined;
46.     if (!submissionId) continue;
47.     const agg = aggregates.get(submissionId);
48.     if (agg) agg.reviewCount += 1;
49.     const bucket = ratingSums.get(submissionId) ?? { sum: 0, count: 0 };
50.     bucket.sum += r.starRating;
51.     bucket.count += 1;
52.     ratingSums.set(submissionId, bucket);
53.   }
54.   for (const [submissionId, bucket] of ratingSums) {
55.     const agg = aggregates.get(submissionId);
56.     if (agg && bucket.count > 0) agg.averageRating = bucket.sum / bucket.count;
57.   }
58. 
59.   return aggregates;
60. }
61. 
62. export interface SubmissionFeedback {
63.   tries: TryRow[];
64.   reviews: ReviewRow[];
65. }
66. 
67. /** Fetches every Try and Review tied to a single submission, for the detail view. */
68. export async function getFeedbackForSubmission(submissionId: string): Promise<SubmissionFeedback> {
69.   const tries = await listTriesForSubmissions([submissionId]);
70.   const tryIds = tries.map((t) => t.rpo_tryid);
71.   const reviews = await listReviewsForTries(tryIds);
72.   return { tries, reviews };
73. }
74.

